CUT = ("One single wide landscape comic panel (3:2) in Japanese gag-manga style, in FULL COLOUR exactly like the first reference panel: bold black ink lines, soft cel colours, warm pastel palette, screentone dots only as subtle texture in the shadows, dramatic speed lines, exaggerated gag reactions. Original characters only. "
 "The hero is the SAME small round chipmunk as the references: orange fur, cream belly, dark brown back stripe, striped tail, a small grey phone with a little red bow charm. Clean thick black panel border. Absolutely no letters, numbers, words, signs or sound-effect lettering anywhere in the image, no speech balloons.")
CUTS = {
 'cut_knock': ("Inside the chipmunk's dark tree-stump home at night. In the background the round wooden door with a small round window; the badger collector's face is pressed close to the window glass, blank eyes staring in, ledger raised. In the foreground the chipmunk hides under a blanket clutching his phone, face pale, eyes huge, sweat drops, trembling. Leave an empty dark area at the top left for lettering.", ['collector']),
 'cut_sign': ("Extreme close-up: the chipmunk's trembling paw grips a pen over a loan contract with only blank lines, wobble lines showing violent shaking, sweat drops falling on the paper. At the edge, the raccoon clerk's paw slides the contract closer with a sugary manicure. Dark violet background with speed lines. Leave an empty area across the top for lettering.", ['raccoon']),
 'cut_streak': ("The chipmunk in a cocky victory pose wearing tiny black sunglasses, arms crossed, chin up, smug grin, a fan of paper acorn banknotes in one paw, sparkles and a bright golden burst background with speed lines. Leave an empty area on the right side for lettering.", []),
 'cut_read': ("Dramatic close-up of the chipmunk's narrowed eyes with a sharp white glint, half his face lit, intense. Behind him a glowing ink-drawn candlestick chart with a clean textbook double-bottom shape completing and breaking upward. Dark blue background with concentrated speed lines. Leave an empty area across the top for lettering.", []),
 'cut_lev100': ("The chipmunk pushes a giant wooden lever slider all the way to its very top with both paws, fur blown back by a storm wind, eyes burning with fire, gritted teeth, sweat flying. The background is a violent red and violet burst with speed lines. Leave an empty area on the left side for lettering.", []),
}
jobs = []
for e in data['endings']:
    scene, gang, gloom = S[e['id']]
    who = [WHO[c] for c in e['cast']]
    txt = STYLE + (" Characters: " + '; '.join(who) + '.' if who else '') + "\nScene: " + scene + (GANG if gang else '') + (DESPAIR if gloom else ' Lighting: warm pastel but sad, despair in the faces.')
    open(os.path.join(HERE, e['id'] + '.txt'), 'w').write(txt + '\n')
    refs = ['docs/art/v5/manga/p1_color.png', 'docs/art/v5/golden/hero_phone.png'] + [REF[c] for c in e['cast']][:2]
    jobs.append((e['id'], 'docs/art/v5/endings_lite/%s.png' % e['id'], refs))
for k, (scene, cast) in CUTS.items():
    who = [WHO[c] for c in cast]
    open(os.path.join(HERE, k + '.txt'), 'w').write(CUT + (" Characters: " + '; '.join(who) + '.' if who else '') + "\nScene, cut-in: " + scene + '\n')
    jobs.append((k, 'docs/art/v5/manga/%s.png' % k.replace('cut_', 'c_'), ['docs/art/v5/manga/p1_color.png', 'docs/art/v5/golden/hero_phone.png'] + [REF[c] for c in cast]))
with open(os.path.join(HERE, 'jobs.tsv'), 'w') as f:
    for j, out, refs in jobs: f.write('\t'.join([j, out, ','.join(refs)]) + '\n')
print(len(jobs), 'jobs')
